1	<?php
2	/**
3	 * Objednavky – seznam a detail.
4	 *
5	 * Editace stavu a slevy je v order_edit.php, hromadne storno v orders.php
6	 * (stare stranky, nikdo je neprepsal).
7	 */
8	
9	namespace App\Legacy\Admin;
10	
11	class OrderController extends BaseController
12	{
13	    protected $title = 'Objednávky';
14	
15	    public function listAction()
16	    {
17	        global $db;
18	        legacy_db();
19	
20	        $status = get_param('status');
21	        $q = get_param('q');
22	        $from = get_param('from');
23	        $to = get_param('to');
24	        list($offset, $limit, $page) = paginate(get_param('page', 1));
25	
26	        $where = " WHERE 1=1";
27	        if ($status != '') {
28	            $where .= " AND o.status = '" . $status . "'";
29	        }
30	        if ($q != '') {
31	            $where .= " AND (o.id LIKE '%" . $q . "%' OR c.email LIKE '%" . $q . "%' OR c.name LIKE '%" . $q . "%')";
32	        }
33	        if ($from != '') {
34	            $where .= " AND o.placed_at >= '" . $from . "'";
35	        }
36	        if ($to != '') {
37	            $where .= " AND o.placed_at <= '" . $to . " 23:59:59'";
38	        }
39	
40	        $total = (int) $db->value("SELECT COUNT(*) FROM orders o LEFT JOIN customers c ON c.id = o.customer_id" . $where);
41	
42	        $orders = $db->query("SELECT o.*, c.name AS customer_name, c.email AS customer_email,"
43	            . " (SELECT SUM(quantity * unit_price_amount_in_cents) FROM order_items WHERE order_id = o.id) AS total,"
44	            . " (SELECT COUNT(*) FROM order_notes WHERE order_id = o.id) AS notes"
45	            . " FROM orders o LEFT JOIN customers c ON c.id = o.customer_id"
46	            . $where
47	            . " ORDER BY o.placed_at DESC"
48	            . " LIMIT " . (int) $limit . " OFFSET " . (int) $offset);
49	
50	        return $this->renderLayout('orders/list', array(
51	            'orders' => $orders,
52	            'status' => $status,
53	            'q'      => $q,
54	            'from'   => $from,
55	            'to'     => $to,
56	            'pager'  => pager_html($page, $total, $limit, admin_url('orders', array('status' => $status, 'q' => $q))),
57	            'total'  => $total,
58	            'states' => $GLOBALS['ORDER_STATES'],
59	        ));
60	    }
61	
62	    public function detailAction()
63	    {
64	        global $db;
65	        legacy_db();
66	
67	        $id = get_param('id');
68	        $order = $db->one("SELECT * FROM orders WHERE id = '" . $id . "'");
69	        if ($order === null) {
70	            return $this->notFound('Objednávka ' . $id . ' neexistuje');
71	        }
72	
73	        $items = $db->query("SELECT i.*, p.name, p.sku FROM order_items i LEFT JOIN products p ON p.id = i.product_id WHERE i.order_id = '" . $id . "' ORDER BY i.id");
74	        $customer = $db->one("SELECT * FROM customers WHERE id = '" . $order['customer_id'] . "'");
75	        $notes = $db->query("SELECT * FROM order_notes WHERE order_id = '" . $id . "' ORDER BY created_at DESC");
76	        $invoice = $db->one("SELECT * FROM invoices WHERE order_id = '" . $id . "'");
77	        $history = $db->query("SELECT * FROM audit_log WHERE entity = 'order' AND entity_id = '" . $id . "' ORDER BY created_at DESC LIMIT 50");
78	
79	        $sum = 0;
80	        foreach ($items as $it) {
81	            $sum += $it['quantity'] * $it['unit_price_amount_in_cents'];
82	        }
83	
84	        return $this->renderLayout('orders/detail', array(
85	            'order'    => $order,
86	            'items'    => $items,
87	            'customer' => $customer,
88	            'notes'    => $notes,
89	            'invoice'  => $invoice,
90	            'history'  => $history,
91	            'sum'      => $sum,
92	            'toPay'    => max(0, $sum - (int) $order['discount_amount_in_cents']),
93	        ), 'Objednávka ' . $id);
94	    }
95	
96	    /**
97	     * Objednavky zakaznika (volano z detailu zakaznika pres AJAX, 2016).
98	     */
99	    public function byCustomerAction()
100	    {
101	        global $db;
102	        legacy_db();
103	        $cid = get_param('customer');
104	        $orders = $db->query("SELECT o.id, o.status, o.placed_at, o.currency FROM orders o WHERE o.customer_id = '" . $cid . "' ORDER BY o.placed_at DESC");
105	        $html = '<ul>';
106	        foreach ($orders as $o) {
107	            $html .= '<li><a href="' . h(admin_url('order', array('id' => $o['id']))) . '">' . h($o['id']) . '</a> – '
108	                . h(order_state_label($o['status'])) . ', ' . format_date($o['placed_at']) . ', '
109	                . format_price(order_total($o['id']), $o['currency']) . '</li>';
110	        }
111	        $html .= '</ul>';
112	
113	        return $html;
114	    }
115	}
