1	<?php
2	/**
3	 * Report skladu. Cte tabulku stock_items (od 2024 ji spravuje novy e-shop),
4	 * rezervace jsou JSON {"orderId": pocet}.
5	 */
6	
7	namespace App\Legacy\lib;
8	
9	class StockReport
10	{
11	    public static function all()
12	    {
13	        global $db;
14	        legacy_db();
15	        $rows = $db->query("SELECT s.product_id, s.on_hand, s.reservations, p.name, p.sku, p.active"
16	            . " FROM stock_items s LEFT JOIN products p ON p.id = s.product_id ORDER BY p.name");
17	
18	        $out = array();
19	        foreach ($rows as $r) {
20	            $reserved = self::reservedQty($r['reservations']);
21	            $r['reserved'] = $reserved;
22	            $r['available'] = (int) $r['on_hand'] - $reserved;
23	            $r['low'] = $r['available'] < config('low_stock', 5);
24	            $out[] = $r;
25	        }
26	
27	        return $out;
28	    }
29	
30	    /**
31	     * Soucet rezervaci z JSONu.
32	     */
33	    public static function reservedQty($json)
34	    {
35	        if ($json === null || $json === '') {
36	            return 0;
37	        }
38	        $data = json_decode((string) $json, true);
39	        if (!is_array($data)) {
40	            return 0;
41	        }
42	        $sum = 0;
43	        foreach ($data as $orderId => $qty) {
44	            $sum += (int) $qty;
45	        }
46	
47	        return $sum;
48	    }
49	
50	    /**
51	     * Rezervace s cisly objednavek (pro detail produktu).
52	     */
53	    public static function reservations($productId)
54	    {
55	        global $db;
56	        legacy_db();
57	        $r = $db->one("SELECT reservations FROM stock_items WHERE product_id = '" . $productId . "'");
58	        if ($r === null) {
59	            return array();
60	        }
61	        $data = json_decode((string) $r['reservations'], true);
62	
63	        return is_array($data) ? $data : array();
64	    }
65	
66	    public static function lowStock()
67	    {
68	        $out = array();
69	        foreach (self::all() as $r) {
70	            if ($r['low']) {
71	                $out[] = $r;
72	            }
73	        }
74	
75	        return $out;
76	    }
77	
78	    /**
79	     * Rucni korekce skladu (inventura). Prepise on_hand primo v tabulce.
80	     * FIXME: novy e-shop o tom nevi, ale funguje to
81	     */
82	    public static function setOnHand($productId, $qty)
83	    {
84	        global $db;
85	        legacy_db();
86	        $db->exec("UPDATE stock_items SET on_hand = " . (int) $qty . " WHERE product_id = '" . $productId . "'");
87	        audit_log('stock', $productId, 'inventura', array('on_hand' => (int) $qty));
88	    }
89	
90	    /**
91	     * Rezervace, jejichz objednavka uz je stornovana (visi tam).
92	     */
93	    public static function orphanReservations()
94	    {
95	        global $db;
96	        legacy_db();
97	        $out = array();
98	        foreach ($db->query("SELECT product_id, reservations FROM stock_items") as $r) {
99	            $data = json_decode((string) $r['reservations'], true);
100	            if (!is_array($data)) {
101	                continue;
102	            }
103	            foreach ($data as $orderId => $qty) {
104	                $o = $db->one("SELECT status FROM orders WHERE id = '" . $orderId . "'");
105	                if ($o === null || $o['status'] == 'cancelled') {
106	                    $out[] = array('product_id' => $r['product_id'], 'order_id' => $orderId, 'qty' => (int) $qty);
107	                }
108	            }
109	        }
110	
111	        return $out;
112	    }
113	}
