88	    public function __invoke(Request $request, string $page = 'dashboard'): Response
89	    {
90	        require_once __DIR__ . '/../bootstrap.php';
91	
92	        if (!isset(self::$pages[$page])) {
93	            return new Response('<h1>404</h1><p>Stránka neexistuje.</p>', 404);
94	        }
95	
96	        // stara administrace cte superglobaly
97	        $_GET = $request->query->all();
98	        $_POST = $request->request->all();
99	        $_REQUEST = array_merge($_GET, $_POST);
100	        $_SERVER['REQUEST_METHOD'] = $request->getMethod();
101	
102	        $GLOBALS['LEGACY_REDIRECT'] = null;
103	        $GLOBALS['LEGACY_STATUS'] = 200;
104	        $GLOBALS['LEGACY_CONTENT_TYPE'] = 'text/html; charset=utf-8';
105	        $GLOBALS['LEGACY_FILENAME'] = null;
106	
107	        $target = self::$pages[$page];
108	        $level = ob_get_level();
109	        ob_start();
110	        try {
111	            if (is_array($target)) {
112	                $controller = new $target[0]();
113	                $result = call_user_func(array($controller, $target[1]));
114	                $html = ob_get_clean() . (is_string($result) ? $result : '');
115	            } else {
116	                $this->includePage(__DIR__ . '/../Admin/' . $target);
117	                $html = ob_get_clean();
118	            }
119	        } finally {
120	            while (ob_get_level() > $level) {
121	                ob_end_clean();
122	            }
123	        }
124	
125	        if (!empty($GLOBALS['LEGACY_REDIRECT'])) {
126	            return new Response('', 302, array('Location' => $GLOBALS['LEGACY_REDIRECT']));
127	        }
128	
129	        $response = new Response($html, (int) $GLOBALS['LEGACY_STATUS']);
130	        $response->headers->set('Content-Type', $GLOBALS['LEGACY_CONTENT_TYPE']);
131	        if (!empty($GLOBALS['LEGACY_FILENAME'])) {
132	            $response->headers->set('Content-Disposition', 'attachment; filename="' . $GLOBALS['LEGACY_FILENAME'] . '"');
133	        }
134	
135	        return $response;
136	    }
137	
138	    /**
139	     * Include ve vlastnim scope, at si stranky neprepisuji promenne mostu.
140	     */
141	    private function includePage($file)
142	    {
143	        include $file;
144	    }
145	}
